import importlib.util
from pyscipopt import Model, quicksum
from collections import defaultdict,Counter
spec=importlib.util.spec_from_file_location('solver','/app/submissions/solve.py')
mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
inst=mod.Instance(); patterns=mod.generate_patterns(inst)
for mult in [1.0,2.0,4.0]:
    model=Model('test')
    mod.configure_scip(model,20)
    y={}
    for o,plist in patterns.items():
        for i,p in enumerate(plist):
            y[o,i]=model.addVar(vtype='B',name=f'y[{o},{i}]')
    pairs=[('ST_A','ST_B'),('ST_A','ST_C'),('ST_B','ST_C')]
    load={s:quicksum(p.total_duration*y[o,i] for o,plist in patterns.items() for i,p in enumerate(plist) if p.station_id==s) for s in inst.stations}
    diff={pair:model.addVar(lb=0,vtype='C',name=f'd[{pair}]') for pair in pairs}
    for o,plist in patterns.items():
        model.addCons(quicksum(y[o,i] for i in range(len(plist)))==1)
    # inventory
    keys=set()
    for plist in patterns.values():
        for p in plist:
            for pod,sku,qty in p.usage_by_pod_sku: keys.add((pod,sku))
    for pod,sku in keys:
        expr=quicksum(qty*y[o,i] for o,plist in patterns.items() for i,p in enumerate(plist) for p2,sku2,qty in p.usage_by_pod_sku if p2==pod and sku2==sku)
        model.addCons(expr<=inst.pod_inventory[pod].get(sku,0))
    # new pod horizon
    for pod in inst.pods:
        expr=quicksum(sum(v.duration + int(inst.pods[pod]['return_buffer_slots']) for v in p.visits if v.pod_id==pod)*y[o,i]
                     for o,plist in patterns.items() for i,p in enumerate(plist))
        model.addCons(expr<=inst.horizon, name=f'podh[{pod}]')
    for s1,s2 in pairs:
        model.addCons(diff[s1,s2]>=load[s1]-load[s2])
        model.addCons(diff[s1,s2]>=load[s2]-load[s1])
    obj=quicksum(p.local_cost*y[o,i] for o,plist in patterns.items() for i,p in enumerate(plist)) + mult*inst.weights['station_imbalance']*quicksum(diff[p] for p in pairs)
    model.setObjective(obj,'minimize')
    model.optimize()
    print('mult',mult,'status',model.getStatus(),'sols',model.getNSols(),'gap',mod.safe_gap(model))
    if model.getNSols()==0: continue
    sel={o: plist[max(range(len(plist)), key=lambda i:model.getVal(y[o,i]))] for o,plist in patterns.items()}
    poddur=Counter(); podblock=Counter(); stationdur=Counter();
    for o,p in sel.items():
        stationdur[p.station_id]+=p.total_duration
        for v in p.visits:
            poddur[v.pod_id]+=v.duration
            podblock[v.pod_id]+=v.duration + int(inst.pods[v.pod_id]['return_buffer_slots'])
    print('stationdur',dict(stationdur))
    print('max poddur',poddur.most_common(8))
    print('max podblock',podblock.most_common(8))
    starts=mod.greedy_order_starts(inst,sel)
    visits,comp,errs=mod.realize_schedule(inst,sel,starts)
    print('greedy starts visits',len(visits),'errs',errs[:3])
    starts,sstatus,sgap,fallback=mod.solve_order_starts(inst,sel,20)
    visits2,comp2,errs2=mod.realize_schedule(inst,sel,starts)
    print('mip starts',sstatus,sgap,'visits',len(visits2),'errs',errs2[:3])
    if not errs2:
        m=mod.compute_metrics(inst,visits2,comp2,sel)
        print('score',m['approx_score'],'max completion',max(comp2.values()))
